export function getMichelinTier(name: string): 'star' | 'bib' | 'recommended' | null {
  const n = name.toLowerCase()
  if ([...MICHELIN_STAR, ...MTY_MICHELIN_STAR, ...ATL_MICHELIN_STAR, ...NYC_MICHELIN_STAR_3, ...NYC_MICHELIN_STAR_2, ...NYC_MICHELIN_STAR_1, ...DAL_MICHELIN_STAR, ...MIA_MICHELIN_STAR, ...CDMX_MICHELIN_STAR, ...CHI_MICHELIN_STAR_3, ...CHI_MICHELIN_STAR_2, ...CHI_MICHELIN_STAR_1, ...LA_MICHELIN_STAR_3, ...LA_MICHELIN_STAR_2, ...LA_MICHELIN_STAR_1, ...HNL_MICHELIN_STAR_2, ...HNL_MICHELIN_STAR_1].some(m => n.includes(m.toLowerCase()))) return 'star'
  if ([...MICHELIN_BIB, ...MTY_MICHELIN_BIB, ...ATL_MICHELIN_BIB, ...NYC_MICHELIN_BIB, ...DAL_MICHELIN_BIB, ...MIA_MICHELIN_BIB, ...CDMX_MICHELIN_BIB, ...CHI_MICHELIN_BIB, ...LA_MICHELIN_BIB, ...HNL_MICHELIN_BIB].some(m => n.includes(m.toLowerCase()))) return 'bib'
  if ([...MICHELIN_RECOMMENDED, ...MTY_MICHELIN_RECOMMENDED].some(m => n.includes(m.toLowerCase()))) return 'recommended'
  return null
}

